#include "readback_layout.h"
#include <cassert>
#include <cstdio>
#include <vector>

int main() {
  using namespace l4d2_readback;
  Layout l;
  assert(layout(1, 1, kDxt1, l) && l.rowBytes == 8 && l.rows == 1 && l.bytes == 8);
  assert(layout(7, 5, kDxt5, l) && l.rowBytes == 32 && l.rows == 2 && l.bytes == 64);
  assert(layout(4096, 4096, kDxt5, l) && l.bytes == 16u * 1024u * 1024u);
  assert(layout(4096, 4096, 21, l) && l.bytes == kMaxBytes);
  assert(!layout(8192, 8192, 21, l));
  assert(!layout(0, 256, 21, l) && !layout(256, 256, 999, l));
  for (const auto format : { kDxt1, kDxt3, kDxt5, 21u, 22u }) {
    assert(layout(7, 5, format, l));
    const auto pitch = l.rowBytes + 31;
    std::vector<uint8_t> source(static_cast<size_t>(pitch) * l.rows, 0xed);
    std::vector<uint8_t> recovered(l.bytes, 0), reference(l.bytes, 0);
    for (uint32_t row = 0; row < l.rows; ++row) {
      for (uint32_t x = 0; x < l.rowBytes; ++x) {
        const auto value = static_cast<uint8_t>((row * 19 + x) ^ 0xa5);
        source[static_cast<size_t>(row) * pitch + x] = value;
        reference[static_cast<size_t>(row) * l.rowBytes + x] = value;
      }
    }
    assert(packRows(source.data(), static_cast<int32_t>(pitch), recovered.data(), l));
    assert(compare(reference.data(), recovered.data(), l.bytes).firstOffset == -1);
    assert(!packRows(source.data(), static_cast<int32_t>(l.rowBytes - 1), recovered.data(), l));
    assert(!packRows(source.data(), -1, recovered.data(), l));
    reference[0] ^= 1; reference[l.bytes - 1] ^= 2;
    const auto difference = compare(reference.data(), recovered.data(), l.bytes);
    assert(difference.mismatchBytes == 2 && difference.firstOffset == 0);
    assert(difference.expected == reference[0] && difference.actual == recovered[0]);
  }
  assert(residencyLayout(1, 3, 28, l) && l.rowBytes == 1 && l.bytes == 3);
  assert(!layout(1, 3, 28, l)); // Phase 1 format eligibility stays unchanged.
  assert(!residencyLayout(256, 256, 999, l));
  assert(residencyLayout(32, 32, kQ8W8V8U8, l) && l.rowBytes == 128 && l.bytes == 4096);
  assert(!layout(32, 32, kQ8W8V8U8, l));
  for (const auto format : { l4d2_ati::kAti1, l4d2_ati::kAti2 }) {
    for (const auto width : { 1u, 2u, 4u, 7u, 32u, 256u }) {
      uint32_t clientPitch = 0; uint64_t clientBytes = 0;
      assert(residencyBackingLayout(width, 7, format, l, clientPitch, clientBytes));
      l4d2_ati::Layout ati; assert(l4d2_ati::layout(width, 7, format, ati));
      assert(l.blockWidth == 4 && l.blockHeight == 4 && l.blockBytes == ati.blockBytes);
      assert(l.bytes == ati.bytes && clientPitch == ati.storagePitch && clientBytes == ati.backingBytes);
      std::vector<uint8_t> source(l.bytes + 32, 0xed), recovered(l.bytes);
      for (uint32_t i = 0; i < l.bytes; ++i) { source[i] = static_cast<uint8_t>(i * 37 + 11); }
      assert(packResidencyRows(source.data(), ati.apiPitch, width, 7, format, recovered.data(), l));
      assert(compare(source.data(), recovered.data(), l.bytes).mismatchBytes == 0);
      assert(packResidencyRows(source.data(), ati.storagePitch, width, 7, format, recovered.data(), l));
      assert(!packResidencyRows(source.data(), -1, width, 7, format, recovered.data(), l));
      assert(!packResidencyRows(source.data(), 0, width, 7, format, recovered.data(), l));
      assert(!layout(width, 7, format, l));
    }
  }
  uint32_t clientPitch = 0; uint64_t clientBytes = 0;
  assert(residencyBackingLayout(8192, 8192, l4d2_ati::kAti1, l, clientPitch, clientBytes));
  assert(l.bytes == 32u * 1024u * 1024u && clientBytes == kMaxBytes);
  assert(!residencyBackingLayout(8192, 8193, l4d2_ati::kAti1, l, clientPitch, clientBytes));
  Selection selection;
  assert(!selection.take(kDxt5, 32, 32, 20));
  assert(selection.take(kDxt5, 256, 256, 20));
  assert(!selection.take(kDxt5, 256, 256, 20));
  assert(selection.take(kDxt5, 4096, 4096, 20));
  assert(!selection.take(kDxt1, 1024, 1024, 2));
  assert(selection.count() == 2);
  puts("PASS: compressed block layout, logical rows without padding, mismatch offsets and deterministic selection");
}
